import BreadcrumbTrail, { type BreadcrumbItem } from '@/components/ui/BreadcrumbTrail.vue'

const fullPath: BreadcrumbItem[] = [
  { label: '项目中心' },
  { label: '智能集群' },
  { label: '微服务节点' },
  { label: '网络拓扑' },
  { label: '动效配置详情' },
]
