    filename: 'useMotion.ts',
    language: 'typescript',
    code: [
      "import { ref, onMounted } from 'vue'",
      '',
      'export function useMotion(targetRef: any) {',
      '  const velocity = ref(0)',
      '  const damping = ref(0.92)',
      '',
      '  function tick() {',
      '    velocity.value *= damping.value',
      '  }',
      '',
      '  return { velocity, tick }',
      '}',
    ],
