import { ref } from 'vue'
import { Plus, Share2, Copy, Bookmark, Settings, Trash2, Edit3 } from 'lucide-vue-next'

interface MenuItem {
  id: string
  label: string
  icon: any
  angle: number // degrees
  distance: number // px
  color: string
}

const isOpen = ref(true)
const hoveredItem = ref<MenuItem | null>(null)

